<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Viewpage/index')}">返回可视化页面</a>|					<a href="{pigcms{:U('index')}" class="on">超值抢购活动列表</a>|					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('add')}','创建活动组',480,300,true,false,false,addbtn,'add',true);">创建活动组</a>				</ul>			</div>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<if condition="$system_session['level'] eq 2 || $system_session['level'] eq 0">								<col width="180" align="center"/>							</if>						</colgroup>						<thead>							<tr>								<th>编号</th>								<th>名称</th>								<th>开始时间</th>								<th>结束时间</th>								<th>活动列表</th>                                <if condition="C('customization.open_view_multi_city') eq 1 ">                                    <th>指定区域</th>                                </if>								<if condition="$system_session['level'] eq 2 || $system_session['level'] eq 0">									<th class="textcenter">操作</th>								</if>							</tr>						</thead>						<tbody>							<if condition="is_array($group_list)">								<volist name="group_list" id="vo">									<tr>										<td>{pigcms{$vo.pigcms_id}</td>										<td>{pigcms{$vo.name}</td>										<td>{pigcms{$vo.begin_time|date='Y-m-d H:i',###}</td>										<td>{pigcms{$vo.end_time|date='Y-m-d H:i',###}</td>										<td><a href="{pigcms{:U('activity_list',array('group_id'=>$vo['pigcms_id']))}">活动列表</a></td>                                        <if condition="C('customization.open_view_multi_city') eq 1 ">                                            <td>                                                <if condition="$vo['city_id'] eq 0">                                                    <font color="green">--</font>                                                    <else/>                                                    <a href="{pigcms{:U('Index/check_area',array('id' => $vo['pigcms_id'],'type'=>'plat_active'))}">                                                        <font color="red">指定区域</font>                                                    </a>                                                </if>                                            </td>                                        </if>										<if condition="$system_session['level'] eq 2 || $system_session['level'] eq 0">											<td class="textcenter"><a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('edit',array('id'=>$vo['pigcms_id']))}','编辑活动分类',480,370,true,false,false,editbtn,'add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="pigcms_id={pigcms{$vo.pigcms_id}" url="{pigcms{:U('del')}" tip="删除活动分类，子分类也会删除！">删除</a></td>										</if>									</tr>								</volist>							<else/>								<tr><td class="textcenter red" colspan="8">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script type="text/javascript">			window.top.contentScrollToTop();		</script><include file="Public:footer"/>